// build wave-1 spec for kumitate round 64 (v1 band 32-64): build + first falsifiers of C1 (report-receipt-diff) and C2 (jj seat containment)
import { writeFileSync } from 'node:fs';
import { LANE, FLEET, BASE, FREEZE, ROUTE, context, mk } from './common.mjs';

const items = [];
const add = mk(items);
const W = `${LANE}/.ufo/waves/round-64/w1`;
const B = `${LANE}/.ufo/waves/round-64/build`;
const ST = `${ROUTE.staged}/knowledge/corpus/knowledge`;
const NORM = `normalise both sides before matching a quote: strip HTML tags and <script>/<style>, decode &amp; &lt; &gt; &quot; &#39; &nbsp;, map curly quotes to ASCII quotes and en/em dashes to "-", delete "**", "__" and backticks, collapse all whitespace to one space (the frozen counter's norm() in ${ROUTE.c2probe} is the reference; read it)`;
const URLS = {
  conc: 'https://docs.jj-vcs.dev/latest/technical/concurrency/',
  ff: 'https://firefox-source-docs.mozilla.org/contributing/jujutsu.html',
  wc: 'https://docs.jj-vcs.dev/latest/working-copy/',
};
const DEMO = `bash ${ROUTE.demo}`;
const OUT = (n) => `${B}/${n}`;

// ======================= SCOUTS (6) =======================
add('K64ScoutConcurrencyOpen', 'scout', `Independently open the jj "Concurrency" technical page and prepare it as a registry row (the lane id it will take is S198).
1. Fetch ${URLS.conc} with curl -sSL (UA 'Mozilla/5.0 (kumitate-r64)'); save the exact bytes to ${OUT('K64ScoutConcurrencyOpen')}/capture/jj-technical-concurrency.html; record HTTP status, Content-Type, Last-Modified/ETag if any, byte size and sha256sum.
2. ${NORM}. Locate and quote verbatim (each <= 25 words, with the heading it sits under, checked to occur in the normalised capture) up to 8 facts: what the operation log is and what it makes possible; lock-free concurrent operation and divergent operations; what is shared between workspaces; anything the page says about working copies and stale workspaces. For each quote run a check proving it occurs in the capture and say how many times.
3. Say which jj version the page documents (the "latest" docs) and whether the host jj is that version (run jj --version). The lane's existing rows hold S066/S067 (v0.45.1 raw docs): state whether this page repeats or adds to them.
End with a ready-to-paste list "- S198 — \\"…\\"" (each line one verified quote).`, ['coverage'], 'open S198 source');

add('K64ScoutFirefoxOpen', 'scout', `Independently open the Firefox Source Docs jj page and prepare it as a registry row (lane id S199).
1. Fetch ${URLS.ff} with curl -sSL (UA 'Mozilla/5.0 (kumitate-r64)'); save to ${OUT('K64ScoutFirefoxOpen')}/capture/firefox-jujutsu.html; record HTTP status, size, sha256sum.
2. ${NORM}. Locate and quote verbatim (<= 25 words, with the section) up to 8 facts from § "Working with multiple workspaces" and any stale-working-copy text: the trigger of a stale workspace, the remedy command, and any configuration knob (the staged note mentions a snapshot auto-update setting — find the exact wording or say the page does not carry it).
3. State what the page is (Mozilla's contributor documentation) and its tier argument: why A for its scope, or why only B.
End with a ready-to-paste list "- S199 — \\"…\\"".`, ['coverage'], 'open S199 source');

add('K64ScoutWorkingCopyOpen', 'scout', `Independently open the jj working-copy documentation (latest) and prepare it as a registry row (lane id S200).
1. Fetch ${URLS.wc} with curl -sSL (UA 'Mozilla/5.0 (kumitate-r64)'); save to ${OUT('K64ScoutWorkingCopyOpen')}/capture/jj-working-copy.html; record HTTP status, size, sha256sum.
2. ${NORM}. Quote verbatim (<= 25 words, with heading) up to 8 facts: § Workspaces (multiple working copies backed by one repo; what creating/forgetting one does to the directory), § Stale working copy (trigger and remedy) and the sentence on automatic snapshotting.
3. The lane already holds S067 = raw.githubusercontent.com/jj-vcs/jj/v0.45.1/docs/working-copy.md (${LANE}/corpus/SOURCES.md). Compare: same document? Do the Workspaces and Stale sections read the same in both? Would a new row for the rendered "latest" page trip the census W04 duplicate-URL rule (different URL string) and would it be a second row about one document in the sense of CORPUS rule 4? Give a recommendation: new row, or reuse S067 and record why.
End with a ready-to-paste list "- S200 — \\"…\\"" (or the reuse recommendation).`, ['coverage'], 'open S200 source');

add('K64ScoutStagedJjDiff', 'scout', `Compare the STAGED jj entries with live evidence, claim by claim — the staged claims are not evidence for this lane.
Read (read-only; run no campaign tool) ${ST}/jj-operation-log-and-seat-staleness-2026-10-25.md, ${ST}/jj-seat-staleness-outcome-2026-10-25.md, ${ST}/jj-seat-workspace-containment-2026-10-24.md, ${ST}/jj-shared-repository-seat-visibility-2026-10-25.md, ${ST}/jj-workspace-as-isolation-substrate-2026-10-24.md and the three ${ST}/agent-isolation-substrates-amendment-*.md. Then run ${DEMO} (hermetic; it builds its own fixtures, prints JJ_SEAT: key=value lines) and read ${LANE}/corpus/knowledge/agent-isolation-substrates.md M7 and the decision table.
For EVERY factual sentence in the two entries named jj-operation-log-and-seat-staleness and jj-seat-staleness-outcome, classify: SUPPORTED-BY-DEMO (name the JJ_SEAT key), SUPPORTED-BY-DOC (you must open the doc and quote), UNSUPPORTED (staged text cites a campaign transcript path the lane cannot cite), CONTRADICTED (give the demo key). Known lead: the staged title "The seat does not go stale" versus the demo keys rewrite_seat_head_seat_state=fresh and abandon_seat_head_seat_state=stale — say exactly what the staged evidence covered. Finish with a table and a recommendation: which sentences the lane entry may carry, which must be cut.`, ['coverage'], 're-ground staged jj entries');

add('K64ScoutStagedScope', 'scout', `Scope-gate the rest of the staged package so the round's lesson records at least one honest REJECT besides the adopted jj entry.
Read ${LANE}/PROVINCE.md (core / frontier / adjacent bands) and ${ROUTE.staged}/MERGE-REPORT.md. Pick SIX staged entries from ${ST}/ OTHER than the jj-* entries, the agent-isolation-substrates amendments, multi-agent-coordinator-topologies.md (admitted round 63), omp-advisor-and-mcp-transports.md and exactly-once-attribution.md (both rejected round 63; their flip conditions are in ${LANE}/corpus/lessons/round-63.md): prefer those whose titles touch orchestration, MCP orchestration, durable execution, isolation, or the lane's own census; include at least one that looks generic or sibling-domain (Japanese/Chinese press accounts, failure-detector bibliography, DOI arbitration).
For each: PROVINCE verdict (core / frontier / adjacent-to-<sibling> / generic-refuse) with the line you applied, whether its cited S-ids resolve in the package SOURCES.append.md and collide with lane ids (grep -oE '^ {0,3}\\|[[:space:]]*S[0-9]{3,}'), the QUALITY.md criteria it trips (${LANE}/corpus/QUALITY.md; name the Q-number), and a one-line ADMIT-CANDIDATE / REJECT with flip condition. Do not adopt anything.`, ['coverage', 'adjacency'], 'scope-gate staged entries');

add('K64ScoutReportCensus', 'scout', `Ground-truth census of the lane's filed reports, built WITHOUT the receipt tool (the tool is judged against your numbers).
The reports live in the fleet repo: git -C ${FLEET} log --format='%h %ad %s' --date=short -- .ufo/reports/round-N/kumitate.md lists commits; read a blob with git -C ${FLEET} show <commit>:.ufo/reports/round-N/kumitate.md (fleet repo is read-only for you; never checkout). For every round N in 30..63 that has a kumitate report: take the FIRST committed blob and the LAST committed blob; for each record bytes, count of '^## SHONEN' headings, count of template tokens (grep -oE '__[A-Z][A-Z0-9_]*__|LANE_HASH|TBD' | wc -l), the list of labelled tallies (grep -oE '[A-Z][A-Z0-9]*_(HELD|UNMET)[ ]+held=[0-9]+/[0-9]+') and whether the first and last blobs differ. Write a TSV ${OUT('K64ScoutReportCensus')}/census.tsv and a summary. Flag every report whose labelled tally has no identical line in the lane's committed receipts for that round (receipts are the files under ${LANE}/.ufo/waves/round-N/{base,close}/; grep them) — that is the hand-derived list the tool must reproduce.`, ['operability'], 'report ground truth');

// ======================= CONNECTORS (4) =======================
add('K64ConnJjSiblingOverlap', 'connector', `Sibling-overlap scan for the jj seat-containment theme (cross-source pattern finding).
grep -rIl in ${FLEET}/*-shokunin/corpus (SOURCES.md, knowledge/, lessons/) and each PROVINCE.md for 'jj workspace', 'workspace add', 'update-stale', 'operation log', 'op log', 'stale working copy', 'seat' near 'jj', 'colocat'. Name which sibling already holds which fact (souji: ${FLEET}/souji-shokunin/corpus/knowledge/jj-colocation-receipts.md; tameshi, tsukuroi, kagi, kasegi: check). Then decide per candidate sentence of a jj seat-containment entry (workspace shares one op log; seat file not visible in default; seat has no .git; rewriting the seat's commit leaves it fresh; abandoning it makes it stale; update-stale recovers; an absolute-path write lands in the default workspace; forget removes registration not the directory) whether it is already a sibling fact (cite, do not restate), a lane fact (corpus/knowledge/agent-isolation-substrates.md M7), or new. Report contested scope as adjacency, never absorbed. Write the decision table.`, ['adjacency', 'coverage'], 'jj sibling overlap');

add('K64ConnForgeryClasses', 'connector', `Cross-round pattern (considerthese idea 1: "try to forge each new gate"): map every forgery or do-nothing class earlier rounds' counters accepted onto this round's two frozen counters and the new tool.
Read ${LANE}/corpus/lessons/round-61.md §Mistakes, round-61-verifier-spotcheck.md (R61-V2), round-62-verifier-spotcheck.md, round-63-verifier-spotcheck.md, ${LANE}/corpus/QUALITY.md Q54-Q59, ${LANE}/corpus/lessons/round-63.md, and the frozen counters ${ROUTE.c1probe} and ${ROUTE.c2probe} plus ${ROUTE.tool}. For each past class (worktree read, substring match, file count, fixture-hosted URL, stub tool, hand-written wave, recomputed pin, ...) say whether R64/J64/the tool accepts it, with a one-command reproducer or a code line showing the guard. List the TEN cheapest forgeries still open against R64 and against J64 (e.g. a report that quotes only unlabelled tallies; a tool special-casing the two real report commits; a J6 demo script that echoes the entry's stated values), ranked by cost to the forger. Do not patch; wave-2 forge seats take your list.`, ['calibration', 'operability'], 'forgery class map');

add('K64ConnIntegrationMap', 'connector', `Integration map: every file and number that must change when the lane adds (a) scripts/report-receipt-diff.mjs, (b) scripts/jj-seat-demo.sh, (c) corpus/knowledge/jj-workspace-seat-containment.md with three registry rows S198-S200, three captures and an appended amendment to corpus/knowledge/agent-isolation-substrates.md, (d) a corpus/lessons/round-64.md and the round-63 spot-check map row.
Trace by reading code (do not guess): scripts/proxy-check.mjs (A, C, C2, C2_total terms, RE_RUNNABLE over walkFiles, GATE_PINS, the kumitate-proxy-v1 stanza and kumitate-gate-pins-v1 block in ${LANE}/SCORECARD.md), scripts/readme-map.mjs + .ufo/pins/readme-map.json, scripts/cite-sources.mjs, scripts/source-capture.mjs + .ufo/pins/source-captures.json, scripts/source-dupes.mjs + its pin, scripts/sources-check.mjs, scripts/claims-check.mjs, SKILL.md gate registry, corpus/README.md. Produce the ordered edit list with exact line anchors, the command that proves each edit, and the order that keeps every gate clean after each step. Also report the current base proxy drift (${LANE}/.ufo/waves/round-64/base/proxy-before.txt: C2_TOTAL_DRIFT, AXES_DRIFT) and what edit repairs each.`, ['operability'], 'integration map');

add('K64ConnRecurrenceCount', 'connector', `Recurrence count (considerthese idea 4): count each routed-defect CLASS across ${LANE}/corpus/lessons/round-*-verifier-spotcheck.md (rounds 40-63) and the round-N-aggregator-* files.
Extract every routed defect id (R<nn>-V<k>, D<k>) with a class label in your own words (map drift, filed-bytes edited in place, placeholder in filed report, number drift between report and receipt, unresolvable hash, counter forgeable, count in prose without receipt, seat-mix below line, ...). Build a table class -> rounds it occurred -> times -> was a gate added after the 3rd occurrence? Mark every class with >= 3 occurrences and say which already has a mechanical gate (name it) and which is still prose-only. Particular interest: the R56-V3 readme-map drift (the spot-check file lands without its README row) — verify the count of occurrences by listing the spot-check files' own words, and say whether report-receipt-diff (${ROUTE.tool}) or readme-map (${LANE}/scripts/readme-map.mjs) would have caught each. Write ${OUT('K64ConnRecurrenceCount')}/recurrence.md.`, ['calibration'], 'recurrence count');

// ======================= EXECUTORS (13) =======================
add('K64ExecReceiptRealRun', 'executor', `Run the receipt tool on every real report and classify each finding true positive or false positive.
Tool: ${ROUTE.tool} (read its header). Reports: for each round N in 40..63 with a lane report in the fleet repo, take the last committed blob (git -C ${FLEET} log --format=%h -n1 -- .ufo/reports/round-N/kumitate.md, then git -C ${FLEET} show <h>:.ufo/reports/round-N/kumitate.md > ${OUT('K64ExecReceiptRealRun')}/r<N>.md) and run node ${ROUTE.tool} --lane ${LANE} --round N --report <file> --rev master --fleet ${FLEET}. Tabulate every finding id and verify by hand (git cat-file, grep of the receipts) whether it is a TRUE positive (the report really says something no receipt/commit supports, or a template token) or a FALSE positive (e.g. external repo hash, legitimate path stem, prose example). Write ${OUT('K64ExecReceiptRealRun')}/classification.tsv. For each false-positive class propose a tool patch (unified diff against ${ROUTE.tool}) that removes it WITHOUT making any control in ${ROUTE.controls} change its verdict (verify by running all 16 cases and the selftest on your patched copy in scratch).`, ['operability'], 'tool on real reports');

add('K64ExecReceiptForge', 'executor', `Forge the receipt tool, then make the forgery fail.
Tool ${ROUTE.tool}; controls ${ROUTE.controls} (format: report.md, lane/ tree, expect). Build in ${OUT('K64ExecReceiptForge')}/cases/ at least 10 report lies that the tool reads CLEAN although a reader would call the report false, in the same control format, each with an expect that states what a sound tool must say: e.g. tally written 'held = 3 / 3' or lower-case, a labelled tally whose receipt is in round N-1 only, a receipt line that names the label with a different x/y on another line while a bare x/y occurs elsewhere in the same file (substring bypass), a hash printed upper-case or abbreviated to 39 digits, a placeholder spelled {{MEASURED}}/XXXX/<measured>/'to be filled', SHONEN heading inside a fenced block, the six headings present only as bold text, a receipt path escaping with ../ or a symlinked receipt, a receipt file that is empty, a tally claimed for a wave whose results file is absent. For each: the cheapest tool change that kills it (unified diff on a scratch copy), and proof (selftest + all 16 controls still pass). Report which forgeries are inherent (cannot be killed without a plan-target/result distinction).`, ['operability', 'calibration'], 'forge receipt tool');

add('K64ExecReceiptMutants', 'executor', `Mutation battery for the receipt tool's own selftest and the 16 controls.
Copy ${ROUTE.tool} into ${OUT('K64ExecReceiptMutants')}/work/ and write mutants.mjs applying ONE single-literal mutant at a time (>= 40: each regex quantifier/anchor, each REQUIRED heading pattern, the SHONEN boxes < 4 threshold, the TALLY regex, the label-match arm of line(), the ancestor test, the tip fallback, exit codes, the round-scoped receipt directories, each finding id). For each mutant run (a) the selftest and (b) the 16 control cases of ${ROUTE.controls} (the invocation the frozen counter ${ROUTE.c1probe} P2 uses). Report killed-by-selftest, killed-by-controls, SURVIVORS (neither). For each survivor either prove it equivalent (reasoning) or write the minimal selftest case or control that kills it (as a patch to the selftest text, never to the frozen controls). Table: id, mutation, killed-by, survivor-verdict.`, ['operability'], 'mutate receipt tool');

add('K64ExecJjHonestFixture', 'executor', `Prove the frozen counter ${ROUTE.c2probe} (JJ64_HELD, checks J1..J8) can read HELD, and that each check can fail alone — before any real entry exists.
Build a hermetic fixture in ${OUT('K64ExecJjHonestFixture')}/: (1) a throwaway lane repo made as D=$(mktemp -d) && git -C "$D" init -q (verify git -C "$D" rev-parse --show-toplevel equals "$D"; all git calls name -C "$D"; commit only inside it with -c user.name=fixture -c user.email=fixture@example.invalid) holding a copy of the lane at ${BASE} plus an honest entry corpus/knowledge/jj-workspace-seat-containment.md, three registry rows inside ## Registry (11 cells, status mined, opened 2026-10-25, used-by naming the entry), captures pinned in .ufo/pins/source-captures.json, a ## Located quotes section (>= 4 bullets), a ## Demo outcomes section copied from a live run of ${DEMO}, a PROVINCE frontier line, a README row (node scripts/readme-map.mjs CLEAN), and an appended 'Amendment 2026-10-25' naming the entry and M7 in agent-isolation-substrates.md. (2) Row URLs may point at a local server you run (python3 -m http.server on 127.0.0.1) serving the captures, so J5's live fetch has something to fetch; state that this is a fixture device (the counter accepts any http(s) URL: carried hole). Run the counter at the fixture commit: it must print JJ64_HELD held=8/8. (3) Generate eight single-fault variants (stale demo value, missing key, quote not in capture, capture bytes edited, row status queued, wrong opened date, PROVINCE line removed, amendment rewritten in place) and show each reads UNMET naming exactly the arm it breaks. If the honest fixture cannot reach 8/8, that is a COUNTER DEFECT: report the failing arm with its message and a proposed counter fix as a diff (a ratchet change the L1 will disclose).`, ['coverage', 'calibration'], 'jj64 reachability');

add('K64ExecJjDemoHarden', 'executor', `Harden the jj seat demo ${ROUTE.demo}.
Run it 10 times sequentially and 4 times in parallel; diff all outputs (must be byte-identical; the jj version line is allowed to be the single constant). Check: no residue left (compare ls /tmp before/after, ~/.config/jj untouched, no process left), it works with HOME set to an empty dir and with JJ_CONFIG unset by caller, it fails closed (exit 2 with the stated message) when jj is absent from PATH (use PATH with only /usr/bin and a stub dir) and when git is absent, it does not depend on the caller's cwd, quoting survives a TMPDIR containing a space. Then extend the demo with three further outcome keys that matter to an orchestrator, each measured not assumed: (a) after 'jj workspace update-stale' on an abandoned seat head, what became of the seat's uncommitted file (recovery commit? still on disk?) — measure; (b) whether two seats that abandon/rewrite each other's heads in turn both end fresh after one 'jj status' each; (c) whether 'jj workspace forget' of a seat leaves its commits reachable (jj log all()). Deliver the extended script as a full-file draft ${OUT('K64ExecJjDemoHarden')}/jj-seat-demo.v2.sh (the L1 decides whether to adopt it; keep the existing 15 keys and their order) plus its run output and a determinism proof (10/10 identical).`, ['operability', 'coverage'], 'harden jj demo');

add('K64ExecCollisionGuard', 'executor', `Assimilation id-collision guard, proven able to fail (addendum item 10).
Work in ${OUT('K64ExecCollisionGuard')}/. 1. Re-run the guard: grep -oE '^ {0,3}\\|[[:space:]]*S[0-9]{3,}' ${LANE}/corpus/SOURCES.md | grep -oE 'S[0-9]+' | sort > reg-ids; the same for ${ROUTE.staged}/SOURCES.append.md > staged-ids; comm -12 reg-ids staged-ids > collisions. Compare with the L1's copies in ${LANE}/.ufo/waves/round-64/assimilation/ (reg 136 ids, staged 155, collisions S195 S196 S197). 2. Prove the guard can fail: in a scratch copy of the registry add the indented row '  | S002 |' style fixture colliding with a staged id (and a column-zero variant, and a 4-space-indented variant that the census parser ignores) and show collisions becomes non-empty for the first two and that the 4-space variant is ignored consistently with scripts/sources-census.sh (run it on each fixture registry). 3. For the jj theme, list the staged jj rows (S259, S270, S271, S280, S290, S291, S295, S309), say which are URL rows vs own-work transcript rows citing campaign paths the lane cannot cite, and write the renumber map by DOCUMENT for the three rows the lane will adopt (S198 = ${URLS.conc}, S199 = ${URLS.ff}, S200 = ${URLS.wc}): staged id -> lane id, with the URL and the shared document rule (CORPUS rule 2, no arithmetic).`, ['calibration'], 'collision guard proof');

add('K64ExecRowsDraft', 'executor', `Build and validate the registry append block for the three rows this round adopts, in a scratch mirror — no staged row is appended as-is.
Rows (document identity decides): S198 = ${URLS.conc}; S199 = ${URLS.ff}; S200 = ${URLS.wc} (S200 is subject to the recommendation of the scout who compares it with held row S067; if you find the page adds nothing beyond S067 say so and draft only S198/S199 plus the reuse of S067). Staged rows to adapt are in ${ROUTE.staged}/SOURCES.append.md (staged S290, S291, S259/S270). Rules: 11 cells, no '|' inside any cell, kind/tier/status per CORPUS.md, status mined, opened 2026-10-25, recheck an ISO date or NNd or symbolic cadence (move any prose to a note), used-by lists exactly corpus/knowledge/jj-workspace-seat-containment.md (and nothing else), anchor names section + revision/date. Open each source yourself (curl) for the anchor and a located <=25-word quote. Mirror: copy ${LANE}/corpus (not the whole lane) to ${OUT('K64ExecRowsDraft')}/validate/corpus/, append the block inside ## Registry, add a placeholder entry file at the used-by path in the mirror, and run /home/vgpnk/Projects/shokunin/scripts/sources-census.sh validate --file ${OUT('K64ExecRowsDraft')}/validate/corpus/SOURCES.md (must exit 0; W04 warnings are allowed, E03/E04 are not) and node ${LANE}/scripts/sources-check.mjs against the mirror if it accepts a root. Deliver ${OUT('K64ExecRowsDraft')}/append-block.md and the validation transcript.`, ['coverage'], 'draft registry rows');

add('K64ExecCaptures', 'executor', `Capture the three source documents and prepare their pin entries.
Fetch ${URLS.conc}, ${URLS.ff}, ${URLS.wc} with curl -sSL (UA 'Mozilla/5.0 (kumitate-r64)') into ${OUT('K64ExecCaptures')}/captures/ (jj-technical-concurrency.html, firefox-jujutsu.html, jj-working-copy.html). Read ${LANE}/scripts/source-capture.mjs (its header and the shape of ${LANE}/.ufo/pins/source-captures.json, e.g. the round-63 entries for S196/S197 and where their capture files live, ${LANE}/.ufo/waves/round-63/build/K63Capture/) and produce the three pin entries (sourceId S198/S199/S200, path under the lane, sha256, bytes, capture date 2026-10-25) exactly in that shape in ${OUT('K64ExecCaptures')}/pins-append.json. Then verify on a scratch copy of the pins file with the three entries appended that node scripts/source-capture.mjs (run in a scratch mirror of the lane containing the captures at the pinned paths) reads CLEAN. Re-fetch each URL a second time and report whether the bytes are stable (sha256 equal) — if a page is dynamic (timestamps, nonces) say so and propose a stable capture (the .md or raw rendering) instead. Note: pages over 1 MiB must be reported (the lane helper skips new files over 1 MiB inside a named directory).`, ['coverage'], 'capture sources');

add('K64ExecReadmeGuard', 'executor', `Structural fix for the R56-V3 recurrence (the round-63 spot-check file landed without its README row; tenth time): make the round-start gate refuse to freeze a plan while readme-map is red.
Read ${LANE}/scripts/plan-before-ready.sh and QUALITY.md Q58 (${LANE}/corpus/QUALITY.md) and ${LANE}/scripts/readme-map.mjs. Design and build, in ${OUT('K64ExecReadmeGuard')}/, an addition so that 'bash scripts/plan-before-ready.sh --round N' also fails closed when 'node scripts/readme-map.mjs' prints DRIFT at the commit that carries the plan (state the exact semantics: evaluate readme-map in a git archive of the plan's commit). Deliver the patched script as a full-file draft, plus a RED-BEFORE receipt: at ${BASE} readme-map exits 1 (first=uncovered:lessons/round-63-verifier-spotcheck.md), so the new arm must exit non-zero for the named reason on an archive of that revision with a plan present, and exit 0 on an archive where the row is present (build the repaired tree in scratch by appending the missing README row and pin per ${LANE}/scripts/readme-map.mjs rules). The fix counts only once shown able to fail: paste both outputs. Also report whether the existing selftest of plan-before-ready covers the new arm and add the case.`, ['operability'], 'readme-map at round start');

add('K64ExecSelftestTranscripts', 'executor', `Routed defect D2: a tally quoted in prose (the gate's "69/69") has no committed transcript. Produce the transcripts and the calibration table.
For every gate script in ${LANE}/scripts/ that has a --selftest (grep -l -- '--selftest' scripts/*.mjs scripts/*.sh), run it in a scratch copy of the lane at the base revision (git archive ${BASE} | tar -x -C ${OUT('K64ExecSelftestTranscripts')}/arch) and save each transcript verbatim to ${OUT('K64ExecSelftestTranscripts')}/transcripts/<script>.txt with its exit code; extract the exact tally line. Then grep ${LANE}/SKILL.md, ${LANE}/SCORECARD.md, ${LANE}/corpus/README.md, ${LANE}/corpus/QUALITY.md and ${LANE}/LOG.md for every statement of the form 'N/N' or 'N cases' tied to a selftest (e.g. inline-dispatch-evidence 69/69, 25 -> 69) and build a table: statement (file:line), claimed tally, observed tally, MATCH/MISMATCH. A mismatch is a calibration finding (self-assessment vs observed state): list each with its file:line. Do not edit any file.`, ['calibration'], 'selftest transcripts + prose tally audit');

add('K64ExecProxyRepair', 'executor', `Diagnose and prepare the repair of the base proxy-check DRIFT.
Base state (${LANE}/.ufo/waves/round-64/base/proxy-before.txt): C2_TOTAL_DRIFT (declared=153 computed=154) and AXES_DRIFT (coverage: ## Axes row=10 derived=9). Read ${LANE}/scripts/proxy-check.mjs and the stanza in ${LANE}/SCORECARD.md (kumitate-proxy-v1 and kumitate-gate-pins-v1 blocks). 1. Explain each drift from the code (what counts as C2 total; why derived=9 for the coverage row — find the cause in the row's text or the derivation rule, not a guess). 2. Write ${OUT('K64ExecProxyRepair')}/refresh-stanza.mjs: given a lane tree (default cwd), recompute every stanza term and gate pin and print the exact replacement stanza text plus a unified diff against SCORECARD.md, WITHOUT writing the lane; the L1 will run it at the end of the round after all files landed. 3. Prove on a git archive of the base that applying your diff turns 'node scripts/proxy-check.mjs' (and --strict) from DRIFT to MATCH, and that your script is idempotent (second run prints an empty diff). Do not edit SCORECARD.md.`, ['operability'], 'proxy repair tool');

add('K64ExecKimiDegraded', 'executor', `Routed defect D4: the proxy stanza K_members 52 -> 49 masks four missing kimi-root members while kimi-census still reads MEMBER_MISSING x4.
Run node ${LANE}/scripts/kimi-census.mjs (read-only on the host ~/.kimi-code) and node ${LANE}/scripts/proxy-check.mjs in a scratch archive of ${BASE}; record both outputs. Identify the four members (names only; never content; no secret values), when each disappeared if the host shows it (stat times of siblings; do not guess), and what corpus/knowledge/kimi-*.md notes still name them. Decide with evidence which of three honest records is right: (a) the members are gone for good (host upgrade) -> retire them from K3 in both member lists; (b) transient -> keep, mark degraded; (c) never reproducible. Deliver ${OUT('K64ExecKimiDegraded')}/proposal.md: the exact patch text for scripts/kimi-census.mjs / scripts/proxy-check.mjs member lists or for SCORECARD wording, a line stating the K layer is DEGRADED if the members stay missing, and the commands showing census and proxy-check agree afterwards on a scratch copy. No change to the real lane.`, ['calibration', 'operability'], 'kimi layer degraded record');

add('K64ExecR63Counts', 'executor', `Calibration sweep of the round-63 report: re-derive every number that can be derived and diff it against the prose.
Report: git -C ${FLEET} show 8fd46e61:.ufo/reports/round-63/kumitate.md. Sources of truth: ${LANE}/.ufo/waves/round-63/w1-results.json, w2-results.json, w1-dispatch.json, w2-dispatch.json, the wave directories w1/ and w2/ (report files), the close/ receipts, git log of the lane (${LANE}), the SCORECARD round-63 section and the spot-check ${LANE}/corpus/lessons/round-63-verifier-spotcheck.md. Check at least 30 statements: seat counts per wave and per role, attack share, m_flash share (strict and loose), model-answer counts (session transcripts under ~/.omp/agent/sessions; count 'model_change' per seat), provider error counts, commit list and the nine hashes, selftest 25->69, controls 14->75, rows 134->136, tier histogram, the '-2' stems count, A/C2/K terms in the stanza. Output ${OUT('K64ExecR63Counts')}/counts.tsv: statement, claimed, derived (command), verdict MATCH/MISMATCH/UNDERIVABLE. Every MISMATCH is a number-drift finding the round-64 report must correct by appended erratum, never a rewrite.`, ['calibration'], 'round-63 number-drift sweep');

